package com.recgombak.batterymonitor;

import android.Manifest; import android.app.*; import android.content.*; import android.content.pm.PackageManager; import android.graphics.*; import android.net.wifi.WifiManager; import android.os.*; import android.view.Gravity; import android.widget.*; import org.json.JSONObject; import java.net.*; import java.nio.charset.StandardCharsets; import java.util.*;

public class MainActivity extends Activity {
 private final Handler ui=new Handler(Looper.getMainLooper()); private final Map<String,DeviceInfo> devices=Collections.synchronizedMap(new HashMap<>()); private LinearLayout list; private TextView subtitle; private Button serviceButton; private volatile boolean listening; private DatagramSocket socket; private WifiManager.MulticastLock lock;
 @Override protected void onCreate(Bundle b){super.onCreate(b);buildUi();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},44);if(Prefs.isEnabled(this))startBatteryService();startListener();ui.post(refresh);}
 private void buildUi(){ScrollView s=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(18),dp(18),dp(30));root.setBackgroundColor(Color.rgb(247,248,250));s.addView(root);root.addView(tv("REC Battery Monitor",27,Color.rgb(15,23,42),true));subtitle=tv("Mengesan tablet dalam Wi-Fi yang sama…",14,Color.DKGRAY,false);root.addView(subtitle);LinearLayout me=card();me.addView(tv("NAMA PERANTI INI",12,Color.GRAY,true));TextView meName=tv(Prefs.getName(this),20,Color.rgb(15,23,42),true);me.addView(meName);Button rename=button("Tukar nama");rename.setOnClickListener(v->rename(meName));me.addView(rename);root.addView(me);serviceButton=button(Prefs.isEnabled(this)?"Henti penghantaran":"Mula penghantaran");serviceButton.setOnClickListener(v->toggle());root.addView(serviceButton);root.addView(tv("PERANTI DALAM WLAN",13,Color.DKGRAY,true));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);TextView foot=tv("Tiada akaun • Tiada Internet • Data hanya dalam Wi-Fi/WLAN tempatan • Kemas kini ±15 saat",12,Color.GRAY,false);root.addView(foot);setContentView(s);}
 private void rename(TextView v){EditText input=new EditText(this);input.setText(Prefs.getName(this));new AlertDialog.Builder(this).setTitle("Nama tablet").setMessage("Contoh: TAB-01").setView(input).setPositiveButton("Simpan",(d,w)->{String n=input.getText().toString().trim();if(!n.isEmpty()){Prefs.setName(this,n);v.setText(n);}}).setNegativeButton("Batal",null).show();}
 private void toggle(){boolean next=!Prefs.isEnabled(this);Prefs.setEnabled(this,next);if(next)startBatteryService();else stopService(new Intent(this,BatteryBroadcastService.class));serviceButton.setText(next?"Henti penghantaran":"Mula penghantaran");}
 private void startBatteryService(){Intent i=new Intent(this,BatteryBroadcastService.class);try{if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception ignored){}}
 private void startListener(){if(listening)return;listening=true;try{WifiManager w=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);lock=w.createMulticastLock("recBatteryLock");lock.setReferenceCounted(false);lock.acquire();}catch(Exception ignored){}new Thread(this::listen,"REC-Battery-Listener").start();}
 private void listen(){try{socket=new DatagramSocket(null);socket.setReuseAddress(true);socket.setBroadcast(true);socket.bind(new InetSocketAddress(BatteryBroadcastService.PORT));socket.setSoTimeout(3000);byte[] buf=new byte[2048];while(listening){try{DatagramPacket p=new DatagramPacket(buf,buf.length);socket.receive(p);JSONObject o=new JSONObject(new String(p.getData(),p.getOffset(),p.getLength(),StandardCharsets.UTF_8));if(!"REC_BATTERY_V1".equals(o.optString("app")))continue;String id=o.optString("id");if(id.isEmpty()||id.equals(Prefs.getId(this)))continue;DeviceInfo d=new DeviceInfo();d.id=id;d.name=o.optString("name","Tablet");d.model=o.optString("model","Android");d.battery=o.optInt("battery",-1);d.charging=o.optBoolean("charging",false);d.lastSeen=System.currentTimeMillis();d.ip=p.getAddress().getHostAddress();devices.put(id,d);}catch(SocketTimeoutException ignored){}catch(Exception ignored){}}}catch(Exception ignored){}finally{if(socket!=null)socket.close();}}
 private final Runnable refresh=new Runnable(){public void run(){render();ui.postDelayed(this,2000);}};
 private void render(){if(isFinishing())return;List<DeviceInfo> data; synchronized(devices){data=new ArrayList<>(devices.values());}data.sort(Comparator.comparingInt(a->a.battery<0?101:a.battery));list.removeAllViews();long now=System.currentTimeMillis();int online=0;for(DeviceInfo d:data)if(now-d.lastSeen<=60000)online++;subtitle.setText(data.isEmpty()?"Belum jumpa tablet. Pastikan semua pada Wi-Fi yang sama.":online+" online • "+data.size()+" pernah dikesan");if(data.isEmpty()){LinearLayout c=card();c.addView(tv("Belum ada peranti dikesan",18,Color.DKGRAY,true));c.addView(tv("Pasang APK yang sama pada semua tablet, tukar nama TAB-01/TAB-02 dan hidupkan penghantaran.",13,Color.GRAY,false));list.addView(c);return;}for(DeviceInfo d:data){boolean on=now-d.lastSeen<=60000;LinearLayout c=card();LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);LinearLayout left=new LinearLayout(this);left.setOrientation(LinearLayout.VERTICAL);left.addView(tv(d.name,20,Color.rgb(15,23,42),true));left.addView(tv(d.model+" • "+d.ip,12,Color.GRAY,false));row.addView(left,new LinearLayout.LayoutParams(0,-2,1));int col=!on?Color.GRAY:d.battery<=20?Color.rgb(220,38,38):d.battery<=40?Color.rgb(217,119,6):Color.rgb(22,163,74);TextView batt=tv((d.battery<0?"--":d.battery)+"%",30,col,true);batt.setGravity(Gravity.END);row.addView(batt,new LinearLayout.LayoutParams(dp(100),-2));c.addView(row);String st=!on?"OFFLINE • bacaan terakhir":""+(d.charging?"⚡ SEDANG DICAS":"● ONLINE");c.addView(tv(st,12,on?Color.DKGRAY:Color.GRAY,true));list.addView(c);}}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(15),dp(16),dp(15));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(16));bg.setStroke(dp(1),Color.LTGRAY);c.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(6));c.setLayoutParams(lp);return c;}
 private TextView tv(String t,int sp,int col,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextSize(sp);v.setTextColor(col);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;} private Button button(String t){Button b=new Button(this);b.setText(t);b.setAllCaps(false);return b;} private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} @Override protected void onDestroy(){listening=false;ui.removeCallbacks(refresh);if(socket!=null)socket.close();if(lock!=null&&lock.isHeld())lock.release();super.onDestroy();}
}
